import 'package:flutter/material.dart';import 'package:intl/intl.dart';import '../../core/data/credit_repository.dart';import '../../shared/irkop_ui.dart';
class CreditsPage extends StatefulWidget{const CreditsPage({super.key,this.businessId});final String? businessId;@override State<CreditsPage> createState()=>_CreditsPageState();}
class _CreditsPageState extends State<CreditsPage>{final _r=CreditRepository();late Future<List<CreditBalance>> _f;@override void initState(){super.initState();_f=_load();}Future<List<CreditBalance>> _load()=>widget.businessId==null?Future.value(const[]):_r.load(widget.businessId!);Future<void> _refresh()async{setState(()=>_f=_load());await _f;}Future<void> _pay(CreditBalance c)async{if(widget.businessId==null)return;final a=TextEditingController();final ok=await showModalBottomSheet<bool>(context:context,isScrollControlled:true,builder:(x)=>Padding(padding:EdgeInsets.fromLTRB(16,16,16,MediaQuery.of(x).viewInsets.bottom+16),child:Column(mainAxisSize:MainAxisSize.min,children:[Text('Bayar '+c.transactionNo,style:Theme.of(x).textTheme.titleLarge),const SizedBox(height:12),TextField(controller:a,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Nominal pembayaran',border:OutlineInputBorder())),const SizedBox(height:12),SizedBox(width:double.infinity,child:FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Simpan Pembayaran')))])));final v=double.tryParse(a.text);if(ok==true&&v!=null&&v>0&&v<=c.balance){try{await _r.pay(businessId:widget.businessId!,credit:c,amount:v);await _refresh();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Pembayaran kasbon disimpan.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Gagal: '+e.toString())));}}a.dispose();}
@override Widget build(BuildContext context){final m=NumberFormat.currency(locale:'id_ID',symbol:'Rp ',decimalDigits:0);return RefreshIndicator(onRefresh:_refresh,child:FutureBuilder<List<CreditBalance>>(future:_f,builder:(c,s){final d=s.data??const <CreditBalance>[];final total=d.fold<double>(0,(x,e)=>x+e.balance);return ListView(padding:const EdgeInsets.all(16),children:[const IrkopSectionHeader(eyebrow:'Piutang',title:'Kasbon',subtitle:'Pantau saldo dan catat pembayaran kasbon.',icon:Icons.credit_score_outlined,action:'Data aktual'),const SizedBox(height:14),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Total Piutang Aktif'),const SizedBox(height:6),Text(m.format(total),style:const TextStyle(fontSize:26,fontWeight:FontWeight.w800))]))),if(s.connectionState!=ConnectionState.done)const Padding(padding:EdgeInsets.all(30),child:Center(child:CircularProgressIndicator())),if(s.hasError)Text('Gagal memuat: '+s.error.toString()),if(!s.hasError&&d.isEmpty)const EmptyStateCard(icon:Icons.credit_score_outlined,title:'Tidak ada kasbon aktif',subtitle:'Transaksi kredit akan muncul di sini.'),...d.map((e)=>Card(child:ListTile(onTap:()=>_pay(e),leading:const CircleAvatar(child:Icon(Icons.account_balance_wallet_outlined)),title:Text(e.transactionNo),subtitle:Text('Terbayar '+m.format(e.paid)+(e.dueDate==null?'':' • Jatuh tempo '+DateFormat('dd/MM/yyyy').format(e.dueDate!))),trailing:Text(m.format(e.balance),style:const TextStyle(fontWeight:FontWeight.w800)))))]);}));}}